                    </div>
                </header>

                <main className="flex-1 p-4 md:p-6 lg:p-8">
                    {children}
                </main>
            </div>
        </div>
    );
}

"use client";

import React, { useState } from "react";
import Link from "next/link";
import { LayoutGrid, List, Plus, Pencil, Trash2, BookOpen, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { CourseCard } from "@/components/CourseCard";
import { cn } from "@/lib/utils";
import { useQuery } from "@tanstack/react-query";

export default function MyCourses() {
    const [viewMode, setViewMode] = useState<"grid" | "table">("table");

    const { data: courses = [], isLoading, error } = useQuery({
        queryKey: ['my-courses'],
        queryFn: async () => {
            const res = await fetch('/api/courses?mode=my');
            if (!res.ok) throw new Error('Failed to fetch courses');
            return res.json();
        }
    });

    if (isLoading) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[400px] text-slate-500">
                <Loader2 className="h-8 w-8 animate-spin mb-2" />
                <p>Loading your courses...</p>
            </div>
        );
    }

    if (error) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[400px] text-red-500">
                <p>Error loading courses. Please try again.</p>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight text-slate-900 dark:text-slate-50">My Courses</h1>
                    <p className="text-slate-500 dark:text-slate-400">Manage the courses you are offering for exchange.</p>
                </div>
                <div className="flex items-center gap-2">
                    <div className="flex items-center bg-white dark:bg-zinc-900 rounded-lg p-1 border border-slate-200 dark:border-zinc-800">
                        <button
                            onClick={() => setViewMode("grid")}
                            className={cn("p-2 rounded-md transition-colors", viewMode === "grid" ? "bg-slate-100 dark:bg-zinc-800 text-slate-900 dark:text-slate-50" : "text-slate-400 hover:text-slate-600")}
                        >
                            <LayoutGrid className="h-4 w-4" />
                        </button>
                        <button
                            onClick={() => setViewMode("table")}
                            className={cn("p-2 rounded-md transition-colors", viewMode === "table" ? "bg-slate-100 dark:bg-zinc-800 text-slate-900 dark:text-slate-50" : "text-slate-400 hover:text-slate-600")}
                        >
                            <List className="h-4 w-4" />
                        </button>
                    </div>
                    <Button asChild className="bg-gradient-to-r from-violet-600 to-emerald-500 hover:from-violet-700 hover:to-emerald-600">
                        <Link href="/dashboard/add-course">
                            <Plus className="mr-2 h-4 w-4" /> Add Course
                        </Link>
                    </Button>
                </div>
            </div>

            {courses.length === 0 ? (
                <div className="text-center py-20 border-2 border-dashed border-slate-200 dark:border-zinc-800 rounded-2xl">
                    <BookOpen className="h-12 w-12 text-slate-300 mx-auto mb-4" />
                    <h3 className="text-lg font-bold text-slate-900 dark:text-slate-50">No courses yet</h3>
                    <p className="text-slate-500 mb-6">Start sharing your knowledge by adding your first course.</p>
                    <Button asChild>
                        <Link href="/dashboard/add-course">Add Course Now</Link>
                    </Button>
                </div>
            ) : viewMode === "grid" ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {courses.map((course: any) => (
                        <div key={course._id} className="relative group">
                            <CourseCard
                                id={course._id}
                                title={course.title}
                                description={course.description}
                                image={course.thumbnailUrl || "https://images.unsplash.com/photo-1633356122544-f134324a6cee?w=800&auto=format&fit=crop&q=60"}
                                platform={course.platform}
                                owner={{
                                    name: course.currentOwner?.name || "You",
                                    image: course.currentOwner?.photoURL
                                }}
                            />
                            <div className="absolute top-2 left-2 px-2 py-1 rounded-md bg-black/60 backdrop-blur-sm text-[10px] font-bold text-white uppercase tracking-wider">
                                {course.status}
                            </div>
                            <div className="absolute top-2 right-2 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                <Button size="icon" variant="secondary" className="h-8 w-8 rounded-full shadow-lg">
                                    <Pencil className="h-4 w-4" />
                                </Button>
                            </div>
                        </div>
                    ))}
                </div>
            ) : (
                <Card className="overflow-hidden border-slate-200 dark:border-zinc-800 bg-white dark:bg-zinc-900">
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-slate-50 dark:bg-zinc-800/50 text-slate-500 dark:text-slate-400 uppercase text-xs font-semibold">
                                <tr>
                                    <th className="px-6 py-4">Course</th>
                                    <th className="px-6 py-4">Platform</th>
                                    <th className="px-6 py-4">Status</th>
                                    <th className="px-6 py-4 text-right">Actions</th>
                                </tr>
                            </thead>
                            <tbody>
                                {courses.map((course: any) => (
                                    <tr key={course._id} className="border-b border-slate-100 dark:border-zinc-800 last:border-0 hover:bg-slate-50 dark:hover:bg-zinc-800/50 transition-colors group">
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-3">
                                                <img src={course.thumbnailUrl || "https://images.unsplash.com/photo-1516321318423-f06f85e504b3?w=100&q=60"} className="h-10 w-16 rounded object-cover bg-slate-200" alt="" />
                                                <div className="font-medium text-slate-900 dark:text-slate-50">{course.title}</div>
                                            </div>
                                        </td>
                                        <td className="px-6 py-4">
                                            <span className="px-2 py-1 rounded-full text-xs font-medium bg-slate-100 text-slate-600 dark:bg-zinc-800 dark:text-slate-300">
                                                {course.platform}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4">
                                            <span className={cn(
                                                "px-2 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider",
                                                course.status === "approved" ? "bg-emerald-100 text-emerald-700" :
                                                    course.status === "rejected" ? "bg-red-100 text-red-700" :
                                                        "bg-amber-100 text-amber-700"
                                            )}>
                                                {course.status}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-right">
                                            <div className="opacity-0 group-hover:opacity-100 transition-opacity flex justify-end gap-2">
                                                <Button size="icon" variant="ghost" className="h-8 w-8 text-slate-500 hover:text-blue-600">
                                                    <Pencil className="h-4 w-4" />
                                                </Button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </Card>
            )}
        </div>
    );
}

"use client";

import React from "react";
import { ArrowRight, CheckCircle, XCircle, Clock, Loader2, Inbox } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { motion, AnimatePresence } from "framer-motion";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useSession } from "next-auth/react";
import { toast } from "sonner";
import { formatDistanceToNow } from "date-fns";

export default function ExchangeRequests() {
    const { data: session } = useSession();
    const queryClient = useQueryClient();
    const userId = session?.user?.id;

    const { data: exchanges, isLoading, error } = useQuery({
        queryKey: ['my-exchanges', userId],
        queryFn: async () => {
            const res = await fetch(`/api/users/${userId}/exchanges`);
            if (!res.ok) throw new Error('Failed to fetch exchanges');
            return res.json();
        },
        enabled: !!userId
    });

    const acceptMutation = useMutation({
        mutationFn: async (id: string) => {
            const res = await fetch(`/api/exchanges/${id}/accept`, { method: 'PATCH' });
            if (!res.ok) {
                const data = await res.json();
                throw new Error(data.error || 'Failed to accept exchange');
            }
            return res.json();
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['my-exchanges'] });
            toast.success("Exchange accepted! Course ownership has been swapped.");
        },
        onError: (err: any) => {
            toast.error(err.message);
        }
    });

    const rejectMutation = useMutation({
        mutationFn: async (id: string) => {
            const res = await fetch(`/api/exchanges/${id}/reject`, { method: 'PATCH' });
            if (!res.ok) throw new Error('Failed to reject exchange');
            return res.json();
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['my-exchanges'] });
            toast.success("Exchange rejected.");
        },
        onError: (err: any) => {
            toast.error(err.message);
        }
    });

    if (isLoading) {
        return (
            <div className="min-h-[400px] flex items-center justify-center">
                <div className="flex flex-col items-center gap-2">
                    <Loader2 className="h-8 w-8 animate-spin text-violet-600" />
                    <p className="text-slate-500">Loading your requests...</p>
                </div>
            </div>
        );
    }

    if (error) {
        return (
            <div className="min-h-[400px] flex items-center justify-center text-red-500">
                Failed to load exchanges.
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="flex flex-col gap-2">
                <h1 className="text-3xl font-bold tracking-tight text-slate-900 dark:text-slate-50">Exchange Requests</h1>
                <p className="text-slate-500 dark:text-slate-400">Manage your incoming and outgoing knowledge trades.</p>
            </div>

            <div className="space-y-4">
                <AnimatePresence mode="popLayout">
                    {exchanges?.length === 0 ? (
                        <motion.div
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            className="bg-white dark:bg-zinc-900 rounded-2xl border border-slate-200 dark:border-zinc-800 p-12 text-center"
                        >
                            <div className="mx-auto w-12 h-12 bg-slate-50 dark:bg-zinc-800 rounded-full flex items-center justify-center mb-4 text-slate-400">
                                <Inbox className="h-6 w-6" />
                            </div>
                            <h3 className="text-lg font-bold text-slate-900 dark:text-slate-50 mb-1">No requests yet</h3>
                            <p className="text-slate-500 text-sm">When you send or receive exchange offers, they will appear here.</p>
                        </motion.div>
                    ) : (
                        exchanges?.map((req: any, i: number) => {
                            const isIncoming = req.toUser?._id === userId;
                            const courseIncoming = isIncoming ? req.offeredCourse : req.requestedCourse;
                            const courseOutgoing = isIncoming ? req.requestedCourse : req.offeredCourse;
                            const partner = isIncoming ? req.fromUser : req.toUser;

                            return (
                                <motion.div
                                    key={req._id}
                                    initial={{ opacity: 0, y: 20 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    exit={{ opacity: 0, scale: 0.95 }}
                                    transition={{ delay: i * 0.1 }}
                                >
                                    <Card className="overflow-hidden border-slate-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 group">
                                        <div className="flex flex-col md:flex-row">
                                            {/* Status Strip */}
                                            <div className={`w-full md:w-2 ${req.status === 'pending' ? 'bg-amber-500' : req.status === 'accepted' ? 'bg-emerald-500' : 'bg-red-500'}`}></div>

                                            <div className="flex-1 p-6">
                                                <div className="flex items-center justify-between mb-4">
                                                    <div className="flex items-center gap-2 text-xs text-slate-500">
                                                        <Clock className="h-3 w-3" />
                                                        {req.createdAt ? formatDistanceToNow(new Date(req.createdAt), { addSuffix: true }) : 'unknown time'}
                                                    </div>
                                                    <span className={`text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full ${req.status === 'pending' ? 'bg-amber-100 text-amber-600' :
                                                            req.status === 'accepted' ? 'bg-emerald-100 text-emerald-600' :
                                                                'bg-red-100 text-red-600'
                                                        }`}>
                                                        {req.status}
                                                    </span>
                                                </div>

                                                <div className="flex flex-col lg:flex-row items-center gap-6">
                                                    {/* What you get */}
                                                    <div className="flex-1 w-full flex gap-4 bg-slate-50 dark:bg-zinc-800/50 p-4 rounded-xl border border-slate-100 dark:border-zinc-800">
                                                        <div className="h-16 w-24 rounded overflow-hidden bg-slate-200 flex-shrink-0">
                                                            <img src={courseIncoming?.thumbnailUrl || "https://images.unsplash.com/photo-1516321318423-f06f85e504b3?w=200&q=60"} className="h-full w-full object-cover" alt="" />
                                                        </div>
                                                        <div className="min-w-0">
                                                            <div className="text-[10px] font-bold text-emerald-600 dark:text-emerald-400 mb-1 uppercase tracking-tight">YOU RECEIVE</div>
                                                            <h3 className="font-bold text-slate-900 dark:text-slate-50 truncate">{courseIncoming?.title || "Unknown Course"}</h3>
                                                            <p className="text-xs text-slate-500 truncate">{courseIncoming?.platform} • {partner?.name || "Someone"}</p>
                                                        </div>
                                                    </div>

                                                    {/* Arrow */}
                                                    <div className="flex-shrink-0 bg-slate-100 dark:bg-zinc-800 p-2 rounded-full text-slate-400">
                                                        <ArrowRight className="h-6 w-6" />
                                                    </div>

                                                    {/* What you give */}
                                                    <div className="flex-1 w-full flex gap-4 bg-slate-50 dark:bg-zinc-800/50 p-4 rounded-xl border border-slate-100 dark:border-zinc-800">
                                                        <div className="h-16 w-24 rounded overflow-hidden bg-slate-200 flex-shrink-0">
                                                            <img src={courseOutgoing?.thumbnailUrl || "https://images.unsplash.com/photo-1516321318423-f06f85e504b3?w=200&q=60"} className="h-full w-full object-cover" alt="" />
                                                        </div>
                                                        <div className="min-w-0">
                                                            <div className="text-[10px] font-bold text-violet-600 dark:text-violet-400 mb-1 uppercase tracking-tight">YOU OFFER</div>
                                                            <h3 className="font-bold text-slate-900 dark:text-slate-50 truncate">{courseOutgoing?.title || "Unknown Course"}</h3>
                                                            <p className="text-xs text-slate-500 truncate">{courseOutgoing?.platform} • Me</p>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>

                                            {/* Actions - Only show if pending and incoming */}
                                            {req.status === 'pending' && isIncoming && (
                                                <div className="border-t md:border-t-0 md:border-l border-slate-100 dark:border-zinc-800 p-6 flex md:flex-col items-center justify-center gap-4 bg-slate-50/50 dark:bg-zinc-800/30">
                                                    <div className="group/accept relative">
                                                        <Button
                                                            size="icon"
                                                            className="h-12 w-12 rounded-full bg-emerald-100 text-emerald-600 hover:bg-emerald-600 hover:text-white shadow-sm transition-all duration-300"
                                                            disabled={acceptMutation.isPending || rejectMutation.isPending}
                                                            onClick={() => acceptMutation.mutate(req._id)}
                                                        >
                                                            {acceptMutation.isPending ? <Loader2 className="h-6 w-6 animate-spin" /> : <CheckCircle className="h-6 w-6" />}
                                                        </Button>
                                                        <span className="absolute -top-10 left-1/2 -translate-x-1/2 bg-slate-900 text-white text-[10px] py-1 px-2 rounded opacity-0 group-hover/accept:opacity-100 transition-opacity whitespace-nowrap pointer-events-none">
                                                            Accept Trade & Swap
                                                        </span>
                                                    </div>
                                                    <div className="group/reject relative">
                                                        <Button
                                                            size="icon"
                                                            variant="ghost"
                                                            className="h-12 w-12 rounded-full bg-red-50 text-red-500 hover:bg-red-500 hover:text-white shadow-sm transition-all duration-300"
                                                            disabled={acceptMutation.isPending || rejectMutation.isPending}
                                                            onClick={() => rejectMutation.mutate(req._id)}
                                                        >
                                                            {rejectMutation.isPending ? <Loader2 className="h-6 w-6 animate-spin" /> : <XCircle className="h-6 w-6" />}
                                                        </Button>
                                                        <span className="absolute -top-10 left-1/2 -translate-x-1/2 bg-slate-900 text-white text-[10px] py-1 px-2 rounded opacity-0 group-hover/reject:opacity-100 transition-opacity whitespace-nowrap pointer-events-none">
                                                            Reject Offer
                                                        </span>
                                                    </div>
                                                </div>
                                            )}

                                            {/* Status Label for non-pending or outgoing */}
                                            {(req.status !== 'pending' || !isIncoming) && (
                                                <div className="border-t md:border-t-0 md:border-l border-slate-100 dark:border-zinc-800 p-6 flex flex-col items-center justify-center min-w-[120px] bg-slate-50/20 dark:bg-zinc-800/10">
                                                    <div className="text-[10px] font-bold text-slate-400 uppercase mb-1">{isIncoming ? 'Received' : 'Sent'}</div>
                                                    <div className={`text-sm font-bold ${req.status === 'accepted' ? 'text-emerald-500' :
                                                            req.status === 'rejected' ? 'text-red-500' :
                                                                'text-amber-500'
                                                        }`}>
                                                        {req.status === 'pending' ? 'Pending Partner' : req.status.charAt(0).toUpperCase() + req.status.slice(1)}
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    </Card>
                                </motion.div>
                            );
                        })
                    )}
                </AnimatePresence>
            </div>
        </div>
    );
}

"use client";

import React from "react";
import { motion } from "framer-motion";
import { Card } from "@/components/ui/card";
import { BookOpen, ArrowLeftRight, TrendingUp, Clock, User as UserIcon } from "lucide-react";
import { useSession } from "next-auth/react";
import { useQuery } from "@tanstack/react-query";
import LoadingSpinner from "@/components/LoadingSpinner";

async function fetchStats() {
    const res = await fetch("/api/user/stats");
    if (!res.ok) throw new Error("Failed to fetch dashboard stats");
    return res.json();
}

export default function DashboardOverview() {
    const { data: session, status: authStatus } = useSession();

    const { data, isLoading, error } = useQuery({
        queryKey: ["userStats"],
        queryFn: fetchStats,
        enabled: authStatus === "authenticated",
    });

    // @ts-expect-error role exists
    const isAdmin = session?.user?.role === "admin";

    if (authStatus === "loading" || isLoading) return <LoadingSpinner />;
    if (error) return <div className="p-8 text-center text-red-500">Failed to load dashboard data. Please try again later.</div>;

    const statsData = data?.stats || {
        ownedCourses: 0,
        pendingRequests: 0,
        totalExchanges: 0,
        exchangeRate: "0%"
    };

    const recentActivity = data?.recentActivity || [];

    const stats = [
        { title: "Owned Courses", value: statsData.ownedCourses.toString(), icon: BookOpen, color: "text-violet-600", bg: "bg-violet-100 dark:bg-violet-900/20" },
        { title: "Incoming Requests", value: statsData.pendingRequests.toString(), icon: Clock, color: "text-amber-600", bg: "bg-amber-100 dark:bg-amber-900/20" },
        { title: "Accepted Trades", value: statsData.totalExchanges.toString(), icon: ArrowLeftRight, color: "text-emerald-600", bg: "bg-emerald-100 dark:bg-emerald-900/20" },
        { title: "Exchange Rate", value: statsData.exchangeRate, icon: TrendingUp, color: "text-blue-600", bg: "bg-blue-100 dark:bg-blue-900/20" },
    ];

    return (
        <div className="space-y-8 p-4 md:p-0">
            <div>
                <motion.h1
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    className="text-3xl font-bold tracking-tight text-slate-900 dark:text-slate-50"
                >
                    Hello, {session?.user?.name?.split(" ")[0] || "Swapper"} 👋
                </motion.h1>
                <motion.p
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: 0.1 }}
                    className="text-slate-500 dark:text-slate-400 mt-1"
                >
                    {isAdmin
                        ? "You have administrative access to manage the platform."
                        : "Welcome back! Here's a real-time look at your skill sharing activity."
                    }
                </motion.p>
            </div>

            {/* Bento Grid Stats */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
                {stats.map((stat, i) => {
                    const Icon = stat.icon;
                    return (
                        <motion.div
                            key={stat.title}
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ delay: i * 0.1 + 0.2 }}
                        >
                            <Card spotlight className="p-6 border-slate-200 dark:border-zinc-800 bg-white dark:bg-zinc-900/50 backdrop-blur-sm">
                                <div className="flex items-center justify-between">
                                    <div>
                                        <p className="text-sm font-medium text-slate-500 dark:text-slate-400">{stat.title}</p>
                                        <h3 className="text-3xl font-bold text-slate-900 dark:text-slate-50 mt-1">{stat.value}</h3>
                                    </div>
                                    <div className={`p-3 rounded-2xl ${stat.bg}`}>
                                        <Icon className={`h-6 w-6 ${stat.color}`} />
                                    </div>
                                </div>
                            </Card>
                        </motion.div>
                    )
                })}
            </div>

            <div className="grid gap-6 grid-cols-1 lg:grid-cols-7">
                <motion.div
                    initial={{ opacity: 0, scale: 0.95 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ delay: 0.6 }}
                    className="col-span-1 lg:col-span-4"
                >
                    <Card className="h-full p-6 border-slate-200 dark:border-zinc-800 bg-white dark:bg-zinc-900/30">
                        <div className="flex items-center justify-between mb-6">
                            <h3 className="text-lg font-bold">Performance Analytics</h3>
                            <span className="text-xs font-semibold px-2 py-1 rounded-md bg-violet-100 text-violet-600 dark:bg-violet-900/30">Auto Update</span>
                        </div>
                        <div className="h-[300px] w-full bg-slate-50/50 dark:bg-zinc-800/50 rounded-2xl flex items-center justify-center border border-dashed border-slate-300 dark:border-zinc-700">
                            <div className="text-center">
                                <TrendingUp className="h-10 w-10 text-slate-300 mx-auto mb-3" />
                                <p className="text-slate-400 font-medium italic">Detailed analytics will appear here as you trade more skills.</p>
                            </div>
                        </div>
                    </Card>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, scale: 0.95 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ delay: 0.7 }}
                    className="col-span-1 lg:col-span-3"
                >
                    <Card className="h-full p-6 border-slate-200 dark:border-zinc-800 bg-white dark:bg-zinc-900/30">
                        <h3 className="text-lg font-bold mb-6">Recent Activity</h3>
                        <div className="space-y-4">
                            {recentActivity.length > 0 ? (
                                recentActivity.map((activity: any, i: number) => {
                                    const isIncoming = activity.toUser?._id === session?.user?.id;
                                    const otherUser = isIncoming ? activity.fromUser : activity.toUser;
                                    const statusColors: any = {
                                        pending: "bg-amber-100 text-amber-600 dark:bg-amber-900/30",
                                        accepted: "bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30",
                                        rejected: "bg-red-100 text-red-600 dark:bg-red-900/30"
                                    };

                                    return (
                                        <div key={activity._id} className="flex items-center justify-between p-4 rounded-2xl bg-slate-50 dark:bg-zinc-800/40 border border-slate-100 dark:border-zinc-700 hover:border-violet-300 dark:hover:border-violet-500/50 transition-all group">
                                            <div className="flex items-center gap-3">
                                                <div className="h-10 w-10 rounded-full bg-slate-200 overflow-hidden ring-2 ring-white dark:ring-zinc-800">
                                                    {otherUser?.photoURL ? (
                                                        <img src={otherUser.photoURL} alt={otherUser.name} className="h-full w-full object-cover" />
                                                    ) : (
                                                        <div className="h-full w-full flex items-center justify-center bg-violet-100 text-violet-600">
                                                            <UserIcon className="h-5 w-5" />
                                                        </div>
                                                    )}
                                                </div>
                                                <div className="max-w-[150px]">
                                                    <p className="text-sm font-bold text-slate-900 dark:text-slate-50 line-clamp-1">{otherUser?.name || "Unknown User"}</p>
                                                    <p className="text-[10px] sm:text-xs text-slate-500 line-clamp-1 italic">
                                                        {isIncoming ? "Requested your" : "Wants to swap for"} "{activity.requestedCourse?.title || "Course"}"
                                                    </p>
                                                </div>
                                            </div>
                                            <span className={`text-[10px] font-bold px-2.5 py-1 rounded-lg ${statusColors[activity.status] || "bg-slate-100 text-slate-600"}`}>
                                                {activity.status.toUpperCase()}
                                            </span>
                                        </div>
                                    );
                                })
                            ) : (
                                <div className="text-center py-10">
                                    <div className="h-12 w-12 bg-slate-100 dark:bg-zinc-800 rounded-full flex items-center justify-center mx-auto mb-4">
                                        <ArrowLeftRight className="h-6 w-6 text-slate-400" />
                                    </div>
                                    <p className="text-slate-500 text-sm">No recent activity found.</p>
                                </div>
                            )}
                        </div>
                    </Card>
                </motion.div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { useSession } from "next-auth/react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { User, Mail, Link as LinkIcon, Save, Camera } from "lucide-react";
import { toast } from "sonner";
import { motion } from "framer-motion";

export default function SettingsPage() {
    const { data: session, update } = useSession();
    const [isLoading, setIsLoading] = useState(false);
    const [formData, setFormData] = useState({
        name: "",
        email: "",
        photoURL: "",
    });

    useEffect(() => {
        if (session?.user) {
            setFormData({
                name: session.user.name || "",
                email: session.user.email || "",
                photoURL: session.user.image || "",
            });
        }
    }, [session]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!session?.user?.id) return;

        setIsLoading(true);
        try {
            const res = await fetch(`/api/users/${session.user.id}`, {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    name: formData.name,
                    photoURL: formData.photoURL,
                }),
            });

            if (!res.ok) throw new Error("Failed to update profile");

            const updatedUser = await res.json();

            // Update the session client-side
            await update({
                ...session,
                user: {
                    ...session.user,
                    name: updatedUser.name,
                    image: updatedUser.photoURL,
                }
            });

            toast.success("Profile updated successfully!");
        } catch (error) {
            console.error(error);
            toast.error("Error updating profile. Please try again.");
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="max-w-4xl mx-auto space-y-8">
            <div>
                <h1 className="text-3xl font-bold tracking-tight text-slate-900 dark:text-slate-50">Account Settings</h1>
                <p className="text-slate-500 dark:text-slate-400">Manage your profile information and preferences.</p>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Profile Preview Card */}
                <div className="lg:col-span-1">
                    <Card className="p-6 border-slate-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 text-center space-y-4">
                        <div className="relative mx-auto w-24 h-24 rounded-full bg-slate-100 flex items-center justify-center overflow-hidden border-2 border-violet-100">
                            {formData.photoURL ? (
                                <img src={formData.photoURL} alt="Profile" className="w-full h-full object-cover" />
                            ) : (
                                <User className="w-10 h-10 text-slate-400" />
                            )}
                            <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 hover:opacity-100 transition-opacity cursor-pointer">
                                <Camera className="w-6 h-6 text-white" />
                            </div>
                        </div>
                        <div>
                            <h3 className="font-bold text-lg text-slate-900 dark:text-slate-50">{formData.name || "Set your name"}</h3>
                            <p className="text-sm text-slate-500">{formData.email}</p>
                        </div>
                        <div className="pt-4 flex flex-wrap gap-2 justify-center">
                            <span className="px-2 py-1 rounded-md bg-violet-50 text-violet-600 text-xs font-semibold border border-violet-100 dark:bg-violet-900/10 dark:text-violet-400">
                                Active Member
                            </span>
                        </div>
                    </Card>
                </div>

                {/* Main Form */}
                <div className="lg:col-span-2">
                    <Card className="p-8 border-slate-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 shadow-sm">
                        <form onSubmit={handleSubmit} className="space-y-6">
                            <div className="space-y-4">
                                <h4 className="text-sm font-semibold text-slate-900 dark:text-slate-50 border-b pb-2">Personal Information</h4>

                                <div className="space-y-2">
                                    <Input
                                        label="Display Name"
                                        value={formData.name}
                                        onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                        placeholder="Enter your full name"
                                        required
                                    />
                                </div>

                                <div className="space-y-2">
                                    <Input
                                        label="Email Address"
                                        value={formData.email}
                                        disabled
                                        className="bg-slate-50 dark:bg-zinc-800 cursor-not-allowed opacity-70"
                                    />
                                    <p className="text-[10px] text-slate-400 italic">Email cannot be changed for security reasons.</p>
                                </div>

                                <div className="space-y-2">
                                    <Input
                                        label="Profile Image URL"
                                        value={formData.photoURL}
                                        onChange={(e) => setFormData({ ...formData, photoURL: e.target.value })}
                                        placeholder="https://example.com/photo.jpg"
                                    />
                                </div>
                            </div>

                            <div className="flex items-center justify-end gap-3 pt-4">
                                <Button
                                    type="submit"
                                    disabled={isLoading}
                                    className="bg-violet-600 hover:bg-violet-700 text-white shadow-lg shadow-violet-500/20 px-6"
                                >
                                    {isLoading ? (
                                        "Saving..."
                                    ) : (
                                        <span className="flex items-center gap-2"><Save className="w-4 h-4" /> Save Changes</span>
                                    )}
                                </Button>
                            </div>
                        </form>
                    </Card>
                </div>
            </div>
        </div>
    );
}

"use client";

